metrics = {
    "CPU":    {"util": 0.62, "queue": 1,  "errors": 0},
    "메모리": {"util": 0.91, "queue": 0,  "errors": 0},
    "디스크": {"util": 0.97, "queue": 14, "errors": 0},
}
for name, m in metrics.items():
    flags = []
    if m["util"] >= 0.9: flags.append("사용률 높음")
    if m["queue"] > 4:   flags.append("대기열 쌓임")
    if m["errors"]:      flags.append("오류")
    print(f"{name}: {m['util']:.0%} 대기 {m['queue']} -> {', '.join(flags) or '정상'}")
# CPU: 62% 대기 1 -> 정상
# 메모리: 91% 대기 0 -> 사용률 높음
# 디스크: 97% 대기 14 -> 사용률 높음, 대기열 쌓임
